insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',1,'The family has two textual branches: ʿĀʾisha''s Ḥirāʾ narrative (10 records) and Jābir b. ʿAbd Allāh''s account of the pause in revelation (12 records). Both are attested in al-Bukhārī and Muslim; Jābir''s branch also in al-Tirmidhī.',array['bukhari:3','muslim:160a','bukhari:4','muslim:161a','tirmidhi:3325']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',2,'Every ʿĀʾisha record in this family passes through ʿUrwa b. al-Zubayr and Ibn Shihāb al-Zuhrī. They are the shared transmitters of that branch. In counting terms, ten records here are one transmitted tradition, not ten independent ones.',array['bukhari:3','bukhari:4953','bukhari:6982','muslim:160a','muslim:160b','muslim:160c']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',3,'Jābir''s branch splits below Abū Salama b. ʿAbd al-Raḥmān. One route goes through al-Zuhrī (via ʿUqayl, Yūnus and Maʿmar). The other goes through Yaḥyā b. Abī Kathīr (via ʿAlī b. al-Mubārak, Ḥarb and al-Awzāʿī). Only the Yaḥyā route has the explicit question-and-answer about which passage came first.',array['bukhari:4922','bukhari:4924','muslim:161d','bukhari:4925','muslim:161a']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',4,'Apparent contradiction (not a direct one): Jābir and Abū Salama answer that al-Muddaththir was revealed first. ʿĀʾisha''s report describes al-ʿAlaq 96:1– being recited at the first encounter. The incompatibility depends on reading the Ḥirāʾ encounter as ''the first Qurʾān revealed''. ʿĀʾisha''s own wording only says revelation began with true dreams.',array['bukhari:3','bukhari:4922','bukhari:4924','muslim:161d']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',5,'Textual evidence relevant to reconciliation, inside Jābir''s own reports: the Prophet calls the figure on the seat ''the angel who came to me at Ḥirāʾ'' (الملك الذي جاءني بحراء). The vision that preceded al-Muddaththir therefore presupposes an earlier Ḥirāʾ encounter. This is a textual observation only. No scholar''s harmonisation is quoted here because none has been checked yet.',array['bukhari:4','bukhari:4925','bukhari:4926','muslim:161a','tirmidhi:3325']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',6,'Divergent detail: bukhari:3 says Waraqa wrote ''the Hebrew script'' (الكتاب العبراني … بالعبرانية). bukhari:4953, bukhari:6982, bukhari:3392 and muslim:160a say ''Arabic'' (العربي … بالعربية). This is a real difference in the stated detail, recorded as divergent and not as a contradiction about the event.',array['bukhari:3','bukhari:4953','bukhari:6982','bukhari:3392','muslim:160a']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',7,'Wording variants that do not change the claim: يرجف فؤاده vs ترجف بوادره (his heart / his neck-muscles trembling), and Khadīja''s يخزيك vs يحزنك (Muslim itself notes Maʿmar''s يحزنك).',array['bukhari:3','muslim:160a','muslim:160b']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'conclusion',8,'bukhari:6982 alone carries the passage on the Prophet''s distress during the pause. It is introduced with فيما بلغنا (''according to what reached us''). That phrase marks it as transmitted differently from the connected narrative around it, so it is an addition (complementary), not a variant of the shared core.',array['bukhari:6982']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'uncertainty',1,'Transmitter identities are normalised by name pattern only (status candidate). Ambiguous names are flagged: ''Yaḥyā'' at the head of bukhari:4922, ''ʿAbd Allāh b. Muḥammad'', ''ʿAbd Allāh'' in bukhari:4953 and ''Ḥarb''. They need a rijāl source before they become verified.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'uncertainty',2,'Who ''فيما بلغنا'' in bukhari:6982 belongs to (al-Zuhrī or another transmitter) is a known question in the commentaries. The pilot does not decide it.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'uncertainty',3,'No named scholarly grading or harmonisation is stored yet. The pilot deliberately quotes none rather than paraphrasing from memory.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'uncertainty',4,'Isnād/matn split is heuristic (splitIsnadMatn, confidence medium). Similarity scores are computed on that split.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'uncertainty',5,'Coverage is limited to QuranHikma''s hadith_corpus_canonical. Parallel reports in Musnad Aḥmad, Ibn Isḥāq/Ibn Hishām, al-Ṭabarī and others are not yet in the family.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='beginning-of-revelation'),'uncertainty',6,'sunnah.com links in hadith_corpus_canonical are wrong for 20 of 22 members: the stored number is from a different numbering scheme. The pilot uses references re-verified by full-text match (ratio 1.0).','grok-bot') on conflict do nothing;
insert into public.hadith_quran_links(family_id,sura_id,aya_from,aya_to,relation,evidence_member_id,evidence_arabic,verification_status) values ((select id from public.hadith_families where slug='beginning-of-revelation'),96,1,3,'quoted_in_text',(select id from public.hadith_family_members where family_id=(select id from public.hadith_families where slug='beginning-of-revelation') and hadith_corpus_canonical_id=85463),'اقرا باسم ربك الذي خلق','source_checked') on conflict do nothing;
insert into public.hadith_quran_links(family_id,sura_id,aya_from,aya_to,relation,evidence_member_id,evidence_arabic,verification_status) values ((select id from public.hadith_families where slug='beginning-of-revelation'),74,1,5,'quoted_in_text',(select id from public.hadith_family_members where family_id=(select id from public.hadith_families where slug='beginning-of-revelation') and hadith_corpus_canonical_id=85464),'يا ايها المدثر','source_checked') on conflict do nothing;
